#include <item/CostumeTransferWire.hpp>
#include <item/SpecialBonusRuntime.hpp>
#include <item/ContainerOpening.hpp>
void CostumeTransferCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,const std::string& password,const std::string& path,const std::vector<BulkSource>& sources){
 using namespace auriga::item;Check(sources.size()==2,"original transfer scroll and its dependent chest");
 CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"owned costume transfer SQL connection");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-costume-transfer-worker").has_value(),"actual native transfer worker starts");
 unsigned serial=0,packets=0;bool replay=false;const auto now=static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());
 const auto op=[&](){++serial;return std::array<std::uint8_t,16>{0x54,static_cast<std::uint8_t>(serial),static_cast<std::uint8_t>(serial>>8)};};
 const auto provision=[&](std::uint64_t pid){const ItemOwner owner{ItemOwnerKind::Character,pid};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};const std::array wallets{ItemWallet{owner,WalletCurrency::Gold,1,1000000}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,wallets).has_value(),"actual transfer owner provisioned");return persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();};
 const auto apply=[&](persistence::LoadedItemOwner& state,const ItemCommit& commit){std::optional<runtime::CommitOutcome> result;Check(runtime::RequestCommit(state.fence.owner,state.fence.sessionGeneration,commit,[&](auto out){result=std::move(out);}),"actual transfer transaction queued");for(unsigned i=0;!result && i<1000;++i){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(result && result->write && result->state,"actual transfer transaction confirmed and reloaded");replay=result->write->replay;if(!replay)runtime::SpendInstanceIds(static_cast<std::size_t>(std::ranges::count_if(commit.items,[](const auto& change){return !change.before;})));state=std::move(*result->state);};
 const auto grant=[&](persistence::LoadedItemOwner& state,ItemGrant spec){spec.createdAtUtcMs=now;spec.tryMagic=spec.key.Category()==ItemCategory::Costume;const auto ids=runtime::PeekInstanceIds(256);Check(ids.size()==256,"reserved real native identities");auto commit=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,ids);Check(commit.has_value(),"real source item grant with its native birth policy planned");const auto id=std::ranges::find_if(commit->items,[](const auto& ch){return !ch.before;})->after.id;apply(state,*commit);return id;};
 const auto find=[&](const persistence::LoadedItemOwner& state,ItemInstanceId id)->const PersistentItem&{return *std::ranges::find(state.items,id,&PersistentItem::id);};
 const auto relog=[&](persistence::LoadedItemOwner& state){const auto prior=state;auto generation=persistence::ClaimOwnerSession(sql,*catalog,state.fence.owner).value();state=persistence::LoadItemOwner(sql,*catalog,state.fence.owner,generation).value();Check(state.items==prior.items && state.wallets==prior.wallets,"copied bonuses, consumption and five-slot stoles survive actual SQL relog");};
 std::array<std::optional<ItemKey>,4> targets;
 for(const auto& [key,entry]:catalog->Entries()){
  if(!catalog->CostumeTransferAllowed(key))continue;
  if(const auto* costume=std::get_if<ItemCostumeRow>(&entry.category);costume && costume->kind<=CostumeKind::Weapon){const auto index=static_cast<unsigned>(costume->kind)-1;const auto* profile=catalog->FindItemAttributes(key);if(!targets[index] && profile && std::ranges::count_if(profile->candidates,[](const auto& v){return v.pool==AttributePool::Normal && v.weight && !v.values.empty();})>=3)targets[index]=key;}
  if(const auto* stole=std::get_if<ItemRegaliaRow>(&entry.category);stole && stole->kind==RegaliaKind::Stole && !targets[3])targets[3]=key;
 }
 Check(std::ranges::all_of(targets,[](const auto& key){return key.has_value();}),"all four real original costume families available");
 for(unsigned n=0;n<sources.size();++n){const auto key=sources[n].grant.key;const auto& entry=*catalog->Find(key);
  const auto file=[&](const std::string& phase,const char* kind,const auto& bytes){std::ofstream out(path+"."+std::to_string(n)+"."+phase+"."+kind+".hex");for(auto b:bytes){auto x=static_cast<unsigned char>(b);out<<"0123456789abcdef"[x>>4]<<"0123456789abcdef"[x&15];}out<<'\n';Check(out.good(),"actual native transfer frame exported");};
  if(std::holds_alternative<ItemBonusToolRow>(entry.category)){
   Check(std::get<ItemBonusToolRow>(entry.category).operation==SpecialBonusOperation::CostumeTransfer,"actual original scroll uses dedicated three-item operation");
   const std::array names{"body","hair","weapon","stole"};
   for(unsigned family=0;family<4;++family){
    auto state=provision(20001+family);const auto scroll=grant(state,{key,0,2}),receiver=grant(state,{*targets[family]}),donor=grant(state,{*targets[family]});
    CostumeTransferActor actor;actor.admitted=actor.alive=actor.nearNpc=true;actor.equipment={255,0,0};actor.equipment.nowUtcMs=now;
    const auto* policy=catalog->FindUsePolicy(entry.base.usePolicy);while(!(policy->allowedClasses&(1u<<actor.equipment.characterClass)))++actor.equipment.characterClass;while(!(policy->allowedSexes&(1u<<actor.equipment.sex)))++actor.equipment.sex;
    if(family<3)for(const auto target:{receiver,donor})Check(std::ranges::count_if(find(state,target).attributes.slots.begin(),find(state,target).attributes.slots.begin()+5,[](const auto& v){return v.has_value();})==3,"real source costume birth policy issues exactly three normal bonuses");
    const auto beforeReceiver=find(state,receiver),beforeDonor=find(state,donor);const auto quote=PrepareCostumeTransfer(*catalog,state.fence.owner,state.items,scroll,receiver,donor,actor);Check(quote.has_value() && quote->kind==family+1,"actual original family admits a real native transfer");
    auto nonce=std::uint64_t{0x5400}+family;
    const auto write=[&](const std::string& step,CostumeTransferStatus status){const auto phase=std::string(names[family])+"_"+step;file(phase,"inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());file(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());const bool preview=status==CostumeTransferStatus::Ready || status==CostumeTransferStatus::Applied;const bool selecting=status==CostumeTransferStatus::Selecting;file(phase,"transfer",EncodeCostumeTransferRuntime(*catalog,{status,preview ? nonce : 0,scroll.Value(),selecting ? 0 : receiver.Value(),selecting ? 0 : donor.Value(),preview ? &*quote : nullptr},state.storages,state.items).value());++packets;};
    write("ready",CostumeTransferStatus::Selecting);
    if(!family){auto refused=actor;refused.nearNpc=false;Check(!PrepareCostumeTransfer(*catalog,state.fence.owner,state.items,scroll,receiver,donor,refused),"NPC refusal never produces a cost");write("denied",CostumeTransferStatus::Denied);}
    write("preview",CostumeTransferStatus::Ready);
    if(!family){auto refused=actor;refused.admitted=false;Check(!MakeCostumeTransferCommit(*catalog,op(),state.fence,state.storages,state.items,scroll,receiver,donor,refused),"stale admission never writes");write("stale",CostumeTransferStatus::Stale);nonce+=0x100;write("repreview",CostumeTransferStatus::Ready);}
    const auto commit=MakeCostumeTransferCommit(*catalog,op(),state.fence,state.storages,state.items,scroll,receiver,donor,actor).value();Check(commit.items.size()==3,"three exact source participants in one SQL transaction");apply(state,commit);
    Check(find(state,scroll).count==1 && std::ranges::find(state.items,donor,&PersistentItem::id)==state.items.end(),"actual SQL spends one scroll and destroys the donor");const auto& after=find(state,receiver);Check(after.key==beforeReceiver.key && after.costume==beforeReceiver.costume && after.attributes==quote->attributes && (family!=3 || after.regalia==quote->stole),"actual SQL receiver preserves identity and lifetime with exact copied source values");
    if(family<3)for(unsigned i=0;i<5;++i)Check(after.attributes.slots[i]==beforeDonor.attributes.slots[i],"actual source ordinary bonuses copied without reroll");else{for(unsigned i=0;i<5;++i)Check(after.regalia->bonuses[i]==beforeDonor.regalia->bonuses[i],"actual source stole bonuses copied without reroll");Check(!after.regalia->bonuses[5],"original cleared sixth slot persists in SQL");}
    write("applied",CostumeTransferStatus::Applied);const auto saved=state.items;apply(state,commit);Check(replay && state.items==saved,"actual receipt replay cannot consume or apply twice");write("replayed",CostumeTransferStatus::Applied);relog(state);write("relogged",CostumeTransferStatus::Applied);
   }
  }else{
   const auto* box=std::get_if<ItemContainerRow>(&entry.category);Check(box && box->lootProfile,"actual dependent source chest");const auto* profile=catalog->FindLoot(*box->lootProfile);Check(profile && profile->Data().entries.size()==17,"all17 original expensive-chest reward rows retained");auto state=provision(20100);auto id=grant(state,{key});
   const auto write=[&](const std::string& phase){file(phase,"inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());file(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());++packets;};const auto initial=find(state,id);file("ready","container",EncodeContainerOpening(*catalog,999,&initial,nullptr,state.fence.revision,ContainerOpeningStatus::Ready,{},{}).value());write("ready");std::uint64_t cursor=0;
   for(unsigned draw=0;draw<17;++draw){if(draw)id=grant(state,{key});const auto before=find(state,id);const auto ids=runtime::PeekInstanceIds(256);const auto opening=MakeContainerOpeningCommit(*catalog,op(),state.fence,state.storages,state.items,state.wallets,{id,{},{255,0,0,false},now},ids,[&](auto maximum){Check(cursor<maximum,"actual original reward interval");return cursor;});Check(opening && opening->won==std::vector<std::uint16_t>{static_cast<std::uint16_t>(draw+1)},"each actual chest row selected by its original weight");apply(state,opening->commit);const auto saved=state.items;const auto wallets=state.wallets;apply(state,opening->commit);Check(replay && state.items==saved && state.wallets==wallets,"chest replay cannot duplicate any reward");const auto phase="opened"+std::to_string(draw);file(phase,"container",EncodeContainerOpening(*catalog,999,&before,nullptr,state.fence.revision,ContainerOpeningStatus::Opened,{},opening->won).value());write(phase);cursor+=profile->Data().entries[draw].weight;}
   relog(state);
  }
 }
 Check(packets==41,"all real source transfer and dependent chest states exported");store.Stop();std::cout<<"SOURCE_COSTUME_TRANSFER_WORKER=SUCCESS sources=2 packets="<<packets<<" checks="<<checks<<std::endl;
}
